int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    size_t iov_offset = 0;
    size_t len = iov_iter_count(iter);
    struct iovec *iov;
    int i, nr_segs, ret = 0;

    if (!iter || !iov_iter_count(iter))
        return -EINVAL;

    iov = iter->iov;
    nr_segs = iter->nr_segs;

    for (i = 0; i < nr_segs; i++) {
        struct iovec *iov_entry = &iov[i];
        struct bio *new_bio;

        new_bio = bio_kmalloc(gfp_mask, 1);
        if (!new_bio) {
            ret = -EINVAL;
            goto unmap_and_exit;
        }

        new_bio->bi_iter = iov_entry->iov_len ? (struct bio_iter) { 0, iov_entry->iov_len } : (struct bio_iter) { 0, 0 };
        new_bio->bi_io_vec[0].bv_page = virt_to_page(iov_entry->iov_base);
        new_bio->bi_io_vec[0].bv_offset = offset_in_page(iov_entry->iov_base);
        new_bio->bi_io_vec[0].bv_len = iov_entry->iov_len;

        bio_chain(rq->bio, new_bio);
        rq->bio = new_bio;
        bio = new_bio;
    }

    rq->cmd_flags |= REQ_COPY_USER;
    return 0;

unmap_and_exit:
    if (bio)
        bio_put(bio);
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    int ret = 0;
    struct bio *bio = NULL;
    struct bio *prev_bio = NULL;
    size_t bytes_mapped = 0;

    if (!iov_iter_is_bvec(iter) && !iov_iter_is_kvec(iter) && !iov_iter_is_iovec(iter))
        return -EINVAL;

    while (iov_iter_count(iter)) {
        bio = bio_alloc(GFP_NOIO, 1);
        if (!bio) {
            ret = -ENOMEM;
            goto unmap_error;
        }

        ret = map_user_io_segment(q, rq, bio, iter, gfp_mask);
        if (ret < 0)
            goto unmap_error;

        if (prev_bio)
            bio_chain(prev_bio, bio);
        else
            rq->bio = bio;

        prev_bio = bio;
        bytes_mapped += bio->bi_iter.bi_size;
    }

    if (bytes_mapped) {
        rq->cmd_flags |= REQ_USER_MAPPED;
    }

    return 0;

unmap_error:
    if (rq->bio)
        bio_unmap_user(rq->bio);
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t total_size = iov_iter_count(iter);
    struct bio *bio = NULL;
    int ret = 0;
    unsigned int nr_segs = 0;

    if (!total_size || !iov_iter_is_linearizable(iter)) {
        return -EINVAL;
    }

    while (iov_iter_peek(iter, 1)) {
        struct bio *new_bio;

        new_bio = bio_alloc(GFP_NOIO, 1);
        if (!new_bio) {
            ret = -EINVAL;
            break;
        }

        if (!bio_map_user_iovec(q, iter, new_bio, gfp_mask)) {
            ret = -EINVAL;
            bio_put(new_bio);
            break;
        }

        if (bio) {
            rq->biotail->bi_next = new_bio;
            rq->biotail = new_bio;
        } else {
            rq->bio = new_bio;
            rq->biotail = new_bio;
        }

        nr_segs++;
    }

    if (ret) {
        while (bio) {
            struct bio *next = bio->bi_next;
            bio_unmap_user(bio);
            bio_put(bio);
            bio = next;
        }
        return ret;
    }

    rq->nr_phys_segments = nr_segs;
    rq->cmd_flags |= REQ_USER_MAPPED;

    return 0;
}

int map_user_iov_to_request(struct request_queue *q, struct request *rq,
                            struct rq_map_data *map_data,
                            const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio;
    struct bio_vec *bvec;
    struct iovec *iov;
    unsigned int nr_vecs;
    size_t iov_len, total_len;
    int i, ret;

    if (!iov_iter_count(iter))
        return 0;

    iov = iter->iov;
    nr_vecs = iter->nr_segs;
    total_len = iov_iter_count(iter);

    bio = bio_alloc(gfp_mask, min_t(unsigned int, nr_vecs, BIO_MAX_PAGES));
    if (!bio)
        return -EINVAL;

    ret = -EINVAL;
    for (i = 0; i < nr_vecs; i++) {
        iov_len = iov[i].iov_len;

        if (iov_len == 0)
            continue;

        bvec = &bio->bi_io_vec[bio->bi_vcnt];
        if (bio_add_page(bio, iov[i].iov_base, iov_len, 0) != iov_len)
            goto unmap_and_out;

        total_len -= iov_len;
    }

    bio->bi_iter.bi_size = total_len;
    ret = blk_rq_map_bio(q, rq, bio);
    if (ret)
        goto unmap_and_out;

    rq->cmd_flags |= REQ_USER_MAPPED;
    return 0;

unmap_and_out:
    bio_unmap_user(bio);
    bio_put(bio);
    return ret;
}

int map_bvec(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio;
    int i, nr_bvecs;
    struct bio_vec *bvec;

    if (iter->nr_segs == 0)
        return -EINVAL;

    nr_bvecs = iov_iter_npages(iter, 0);
    if (!nr_bvecs)
        return -EINVAL;

    bio = bio_alloc(gfp_mask, nr_bvecs);
    if (!bio)
        return -EINVAL;

    for (i = 0; i < iter->nr_segs; i++) {
        const struct iovec *iov = &iter->iov[i];
        int len = iov->iov_len;
        void *buf = iov->iov_base;
        unsigned long off;

        if (!access_ok(VERIFY_READ, buf, len)) {
            bio_free(bio);
            return -EINVAL;
        }

        off = (unsigned long) buf & (SECTOR_SIZE - 1);
        if (off) {
            len -= off;
            if (!len) {
                bio_free(bio);
                return -EINVAL;
            }
        }

        bvec = &bio->bi_io_vec[bio->bi_vcnt];
        bvec->bv_page = virt_to_page(buf);
        bvec->bv_len = len;
        bvec->bv_offset = off;

        bio->bi_vcnt++;
        rq->nr_phys_segments++;
    }

    rq->biotk = bio->bi_bdev->bd_disk->queue->elevator->type;
    rq->flags |= REQ_MAPPED;

    return 0;
}
